import { SheetBody } from '../../slots/defs/sheetBody';
import { useClaims } from '../claims/claims';
import { usePeople } from '../people/people';
import { sumDue, useRates } from '../rates/rates';
import { useSheetToday } from '../sheet/sheet';
import { useCap, useFloor, useLate } from '../access/access';
import { useAsOf } from '../sheet/asof.slot';
import { sheetFigures, useDescendantFigures } from './consolidated';

// The consolidated figures, over the sheet and all its descendants: everyone on them, and each
// sheet's due-total and overdue-total as that sheet shows them, added up. The sheet's own figures
// are the header's; with no children these are just those. While the screen shows an as-of date,
// every sheet of the tree is shown as it stood at the end of that date, with that date as its today.
function Consolidated({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const [asOf] = useAsOf();
  const descendants = useDescendantFigures(sheetId, asOf).data ?? [];

  const own = sheetFigures(people, claims, rates, today, floor, late, cap);
  const all = [own, ...descendants];
  const count = all.reduce((n, f) => n + f.people, 0);

  return (
    <section data-testid="consolidated">
      Consolidated — People: <strong data-testid="consolidated-people-count">{count}</strong>{' '}
      Due: <strong data-testid="consolidated-due-total">{sumDue(all.map((f) => f.dueTotal))}</strong>{' '}
      Overdue: <strong data-testid="consolidated-overdue-total">{sumDue(all.map((f) => f.overdueTotal))}</strong>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: -99.5, Component: Consolidated });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import type { Claim } from '../claims/claims';
import { liveHolds } from '../people/people';
import type { Person } from '../people/people';
import { personDueTotal, trimmedSumDue } from '../rates/rates';
import type { Dated, Late, Rate } from '../rates/rates';
import { personOverdue } from '../overdue/overdue';
import { floorOf, lateOf } from '../access/access';
import type { Settings } from '../access/access';
import type { Sheet } from '../sheet/sheet';

/** A sheet's own figures, as its header shows them: its people, its due-total and its overdue-total. */
export type Figures = { people: number; dueTotal: string; overdueTotal: string };

/** A sheet's figures from what it holds — the one working the header and the consolidated figures share. */
export function sheetFigures(
  people: Person[],
  claims: Claim[],
  rates: Rate[],
  today: string,
  floor: Dated,
  late: Late,
  cap: string,
): Figures {
  const claimsOf = (id: string) => claims.filter((c) => c.personId === id);
  return {
    people: people.length,
    dueTotal: trimmedSumDue(
      people.map((p) => personDueTotal(rates, p.grades, today, claimsOf(p.id), liveHolds(p, today), floor, late, cap)),
    ),
    overdueTotal: trimmedSumDue(
      people.map((p) => personOverdue(rates, p.grades, today, claimsOf(p.id), liveHolds(p, today), floor, late).total),
    ),
  };
}

const enc = encodeURIComponent;

/**
 * A sheet's figures, every part of it read fresh from the store: as it is now, or, while the screen
 * shows an as-of date, as it stood at the end of that date (each read names it, and the sheet read
 * answers with that date as its today).
 */
async function readFigures(sheetId: string): Promise<Figures> {
  const [sheet, people, claims, rates, settings] = await Promise.all([
    getJson<Sheet>(`/api/sheets/${enc(sheetId)}`),
    getJson<{ people: Person[] }>(`/api/sheets/${enc(sheetId)}/people`).then((r) => r.people),
    getJson<{ claims: Claim[] }>(`/api/sheets/${enc(sheetId)}/claims`).then((r) => r.claims),
    getJson<{ rates: Rate[] }>(`/api/sheets/${enc(sheetId)}/rates`).then((r) => r.rates),
    getJson<Settings>(`/api/sheets/${enc(sheetId)}/settings`),
  ]);
  return sheetFigures(people, claims, rates, sheet.today, floorOf(settings), lateOf(settings, sheet.today), settings.cap ?? '');
}

/**
 * The figures of each of the sheet's descendants: the sheets naming it as their parent, theirs, and
 * so on, each as the screen's as-of date shows it (as it is now while none is set). Kept under the
 * sheet's own key with the as-of date, so loading the sheet again, or changing the date, re-reads them all.
 */
export function useDescendantFigures(sheetId: string, asOf: string) {
  return useQuery({
    queryKey: ['sheet', sheetId, 'descendants', asOf] as const,
    queryFn: async () => {
      const { descendants } = await getJson<{ descendants: string[] }>(`/api/sheets/${enc(sheetId)}/descendants`);
      return Promise.all(descendants.map(readFigures));
    },
  });
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { isReviewLate, useClaims } from '../claims/claims';
import type { ClaimStatus } from '../claims/claims';
import { GRADES, liveHolds, usePeople } from '../people/people';
import type { Person } from '../people/people';
import { diffDue, personDueTotal, sumDue, useRates } from '../rates/rates';
import { useCap, useFloor, useLate, useReviewSla } from '../access/access';
import { useSheetToday } from '../sheet/sheet';
import { periodDueTotal, usePeriods } from '../periods/periods';
import { isActive } from '../active/active';
import { useVoidReasons } from '../voidreasons/voidReasons';

// Every status the summary counts.
const STATUSES: ClaimStatus[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'];

// The sheet's summary, worked from the same figures as the lists: per grade, the people on it today
// (retired people left out), their due-totals added up and how many of them are active; per
// period, its due-total and its change from the period before it by from-date (none for the
// earliest); per status, how many claims have it; per void reason on the list, how many
// VOID claims were voided with it; and how many claims are late for review.
function Summary({ sheetId }: { sheetId: string }) {
  const people = usePeople(sheetId).data ?? [];
  const claims = useClaims(sheetId).data ?? [];
  const rates = useRates(sheetId).data ?? [];
  const periods = usePeriods(sheetId).data ?? [];
  const today = useSheetToday(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const cap = useCap(sheetId);
  const reviewSla = useReviewSla(sheetId);
  const voidReasons = useVoidReasons(sheetId).data ?? [];

  const active = people.filter((p) => !p.retired);
  const claimsOf = (p: Person) => claims.filter((c) => c.personId === p.id);
  const dueOf = (p: Person) => personDueTotal(rates, p.grades, today, claimsOf(p), liveHolds(p, today), floor, late, cap);

  return (
    <section data-testid="summary">
      <h2>Summary</h2>
      <table>
        <thead>
          <tr>
            <th>Grade</th>
            <th>People</th>
            <th>Due</th>
            <th>Active</th>
          </tr>
        </thead>
        <tbody>
          {GRADES.map((g) => {
            const onGrade = active.filter((p) => p.grade === g);
            return (
              <tr key={g}>
                <td>{g}</td>
                <td data-testid={`summary-grade-${g}-count`}>{onGrade.length}</td>
                <td data-testid={`summary-grade-${g}-due-total`}>{sumDue(onGrade.map(dueOf))}</td>
                <td data-testid={`summary-grade-${g}-active`}>
                  {onGrade.filter((p) => isActive(claimsOf(p), liveHolds(p, today), today)).length}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Period</th>
            <th>Due</th>
            <th>Change</th>
          </tr>
        </thead>
        <tbody>
          {periods.map((p) => {
            const due = periodDueTotal(p, people, claims, rates, floor, late);
            const previous = [...periods].sort((a, b) => (a.from < b.from ? -1 : a.from > b.from ? 1 : 0)).filter((q) => q.from < p.from).pop();
            return (
              <tr key={p.name}>
                <td>{p.name}</td>
                <td data-testid={`summary-period-${p.name}-due-total`}>{due}</td>
                <td data-testid={`summary-period-${p.name}-change`}>
                  {previous ? diffDue(due, periodDueTotal(previous, people, claims, rates, floor, late)) : ''}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Status</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td data-testid={`summary-status-${s}-count`}>{claims.filter((c) => c.status === s).length}</td>
            </tr>
          ))}
          <tr>
            <td>REVIEW late</td>
            <td data-testid="summary-review-late-count">{claims.filter((c) => isReviewLate(c, today, reviewSla)).length}</td>
          </tr>
        </tbody>
      </table>
      <table>
        <thead>
          <tr>
            <th>Void reason</th>
            <th>Claims</th>
          </tr>
        </thead>
        <tbody>
          {voidReasons.map(({ reason }) => (
            <tr key={reason}>
              <td>{reason}</td>
              <td data-testid={`summary-void-${reason}-count`}>
                {claims.filter((c) => c.status === 'VOID' && c.voidReason === reason).length}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}

export const contribution = SheetBody.fill({ order: 30, Component: Summary });

